<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">find_package</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(rayrai CONFIG REQUIRED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATHS</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;\${CMAKE_CURRENT_SOURCE_DIR}/sdk&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NO_DEFAULT_PATH NO_CMAKE_FIND_ROOT_PATH)</span></span>
